```python
#!/usr/bin/env python3
"""Rename photos to YYYY-MM-DD_NNN.ext using the date each photo was taken.

Preview (no changes):  python rename_photos.py [folder]
Apply:                 python rename_photos.py [folder] --apply

Needs Pillow:  python -m pip install Pillow
(Optional, for iPhone HEIC files: python -m pip install pillow-heif)
"""

from __future__ import annotations

import argparse
import datetime as dt
import os
import re
import sys
from pathlib import Path

try:
    from PIL import Image
except ImportError:
    sys.exit("This script needs Pillow:  python -m pip install Pillow")

try:  # HEIC/HEIF support, if installed
    import pillow_heif

    pillow_heif.register_heif_opener()
except ImportError:
    pass

PHOTO_EXTS = {
    ".jpg", ".jpeg", ".png", ".tif", ".tiff", ".webp",
    ".heic", ".heif", ".dng", ".cr2", ".nef", ".arw",
    ".raf", ".orf", ".rw2", ".pef", ".srw",
}

# 2024-05-12, 2024_05_12, 20240512, IMG-20240512-WA0001 ...
DATE_IN_NAME = re.compile(
    r"(?<!\d)((?:19|20)\d{2})[-_.]?(0[1-9]|1[0-2])[-_.]?(0[1-9]|[12]\d|3[01])(?!\d)"
)
ALREADY_NAMED = re.compile(r"^\d{4}-\d{2}-\d{2}_\d{3,}$", re.I)


def parse_exif_date(value):
    if value is None:
        return None
    if isinstance(value, bytes):
        value = value.decode("ascii", "ignore")
    text = str(value).replace("\x00", "").strip()
    for fmt in ("%Y:%m:%d %H:%M:%S", "%Y-%m-%d %H:%M:%S", "%Y:%m:%d %H:%M"):
        try:
            return dt.datetime.strptime(text, fmt)
        except ValueError:
            continue
    return None


def add_subsec(moment, subsec):
    if subsec is None:
        return moment
    digits = re.sub(r"\D", "", str(subsec))
    if not digits:
        return moment
    return moment.replace(microsecond=int((digits + "000000")[:6]))


def exif_taken(path):
    """Date the camera recorded, or None."""
    try:
        with Image.open(path) as img:
            exif = img.getexif()
            if not exif:
                return None
            try:
                sub = exif.get_ifd(0x8769)  # Exif sub-IFD
            except Exception:
                sub = {}
            subsec = sub.get(0x9291)  # SubSecTimeOriginal
            for tag in (0x9003, 0x9004):  # DateTimeOriginal, DateTimeDigitized
                taken = parse_exif_date(sub.get(tag))
                if taken:
                    return add_subsec(taken, subsec)
            return parse_exif_date(exif.get(0x0132))  # DateTime
    except Exception:
        return None


def date_from_name(path):
    match = DATE_IN_NAME.search(path.stem)
    if not match:
        return None
    year, month, day = (int(part) for part in match.groups())
    try:
        return dt.datetime(year, month, day, 12, 0, 0)  # noon: keeps day order sane
    except ValueError:
        return None


def taken_datetime(path, stats):
    taken = exif_taken(path)
    if taken:
        return taken, "EXIF"
    taken = date_from_name(path)
    if taken:
        return taken, "filename"
    return dt.datetime.fromtimestamp(stats.st_mtime), "file date"


def main(argv=None):
    parser = argparse.ArgumentParser(
        description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter
    )
    parser.add_argument("folder", nargs="?", default=".", help="folder with the photos (default: .)")
    parser.add_argument("--apply", action="store_true", help="actually rename; without this it is a dry run")
    parser.add_argument("-r", "--recursive", action="store_true", help="include subfolders")
    parser.add_argument("--include-named", action="store_true",
                        help="also process files already named YYYY-MM-DD_NNN")
    args = parser.parse_args(argv)

    root = Path(args.folder).expanduser().resolve()
    if not root.is_dir():
        sys.exit(f"Not a folder: {root}")

    globber = root.rglob("*") if args.recursive else root.glob("*")
    photos = []
    for path in sorted(globber):
        if not path.is_file() or path.suffix.lower() not in PHOTO_EXTS:
            continue
        if not args.include_named and ALREADY_NAMED.match(path.stem):
            continue
        try:
            stats = path.stat()
        except OSError:
            continue
        taken, source = taken_datetime(path, stats)
        photos.append({"path": path, "taken": taken, "source": source, "mtime": stats.st_mtime})

    if not photos:
        print(f"No photos to rename in {root}")
        return 0

    # Oldest first, so the numbering inside a day matches shooting order.
    photos.sort(key=lambda p: (p["taken"], p["mtime"], p["path"].name.lower()))

    source_paths = {str(p["path"]) for p in photos}
    counters, assigned = {}, set()

    for item in photos:
        day = item["taken"].strftime("%Y-%m-%d")
        ext = item["path"].suffix.lower()
        n = counters.get(day, 1)
        while True:
            target = item["path"].with_name(f"{day}_{n:03d}{ext}")
            free = str(target) not in assigned and (
                not target.exists() or str(target) in source_paths
            )
            if free:
                break
            n += 1
        counters[day] = n + 1
        assigned.add(str(target))
        item["target"] = target

    for item in photos:
        print(f"{item['path'].name}  ->  {item['target'].name}   [{item['source']}]")

    guessed = sum(1 for p in photos if p["source"] != "EXIF")
    if guessed:
        print(f"\nNote: {guessed} file(s) had no EXIF date; they use the filename or file date.")

    if not args.apply:
        print(f"\nPreview only: {len(photos)} photo(s) would be renamed. Re-run with --apply.")
        return 0

    # Two passes so photos can swap names without overwriting each other.
    staged = []
    try:
        for i, item in enumerate(photos):
            tmp = item["path"].with_name(f".rename-tmp-{os.getpid()}-{i}{item['path'].suffix.lower()}")
            item["path"].rename(tmp)
            staged.append((tmp, item["target"], item["path"]))
        for tmp, target, _src in staged:
            tmp.rename(target)
    except OSError as exc:
        print(f"\nError while renaming: {exc}\nRolling back...", file=sys.stderr)
        for tmp, target, src in reversed(staged):
            for candidate in (tmp, target):
                if candidate.exists():
                    try:
                        candidate.rename(src)
                    except OSError:
                        pass
                    break
        return 1

    print(f"\nRenamed {len(photos)} photo(s).")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
```

Usage:

```bash
cd /path/to/folder
python rename_photos.py            # preview
python rename_photos.py --apply    # do it
```

Behaviour worth knowing:

- **Date source order:** EXIF `DateTimeOriginal` → `DateTimeDigitized` → `DateTime` → date found in the filename → file modification date (flagged in the output).
- **Numbering resets each day** (`2024-05-12_001.jpg`, `_002`, …) and follows capture time, so burst shots keep their order.
- **No overwrites:** an existing file never gets clobbered; numbering skips ahead instead.
- **Re-runnable:** files already named `YYYY-MM-DD_NNN.ext` are skipped by default, so running twice does nothing the second time.
- Extensions are lowercased (`.JPG` → `.jpg`); `-r` includes subfolders.

Try the preview first and check the `[EXIF]` / `[filename]` / `[file date]` markers — if a lot say "file date", the photos likely have no EXIF and you may want to tell me before applying.
